#include "PluginProcessor.h"

#include <cmath>
#include <iostream>

namespace {
int failures=0;
void expect(bool condition,const char*message){if(!condition){std::cerr<<"FAIL: "<<message<<'\n';++failures;}}
juce::AudioBuffer<float> tone(float frequency,float amplitude=0.8f){juce::AudioBuffer<float>buffer(2,48000);for(int sample=0;sample<buffer.getNumSamples();++sample){const auto value=amplitude*std::sin(juce::MathConstants<float>::twoPi*frequency*sample/48000.0f);buffer.setSample(0,sample,value);buffer.setSample(1,sample,value*.7f);}return buffer;}
juce::AudioBuffer<float> burst(){auto buffer=tone(1000,.15f);for(int sample=0;sample<4800;++sample)for(int channel=0;channel<2;++channel)buffer.setSample(channel,sample,buffer.getSample(channel,sample)*6.0f);return buffer;}
float power(const juce::AudioBuffer<float>&buffer){double result=0;for(int channel=0;channel<buffer.getNumChannels();++channel)for(int sample=0;sample<buffer.getNumSamples();++sample)result+=buffer.getSample(channel,sample)*buffer.getSample(channel,sample);return static_cast<float>(result/(buffer.getNumChannels()*buffer.getNumSamples()));}
float difference(const juce::AudioBuffer<float>&a,const juce::AudioBuffer<float>&b){double result=0;for(int channel=0;channel<a.getNumChannels();++channel)for(int sample=0;sample<a.getNumSamples();++sample)result+=std::abs(a.getSample(channel,sample)-b.getSample(channel,sample));return static_cast<float>(result);}
void set(DoziGlueCompressorProcessor&processor,const char*id,float plain){auto*parameter=dynamic_cast<juce::RangedAudioParameter*>(processor.parameters.getParameter(id));parameter->setValueNotifyingHost(parameter->convertTo0to1(plain));}
}

int main(){
    DoziGlueCompressorProcessor processor;processor.prepareToPlay(48000,512);
    struct Expected{const char*id;float minimum,maximum,defaultValue;};
    for(const auto&item:{Expected{"threshold",-40,10,-11.4f},Expected{"attack",.1f,100,80},Expected{"release",50,1000,300},Expected{"ratio",1,20,1.1f},Expected{"makeupGainDb",-18,12,0}}){auto*parameter=dynamic_cast<juce::RangedAudioParameter*>(processor.parameters.getParameter(item.id));expect(parameter!=nullptr,"required existing parameter ID is present");if(parameter){expect(std::abs(parameter->getNormalisableRange().start-item.minimum)<1e-4f,"parameter minimum matches hardware");expect(std::abs(parameter->getNormalisableRange().end-item.maximum)<1e-4f,"parameter maximum matches hardware");expect(std::abs(parameter->convertFrom0to1(parameter->getDefaultValue())-item.defaultValue)<1e-3f,"parameter default is preserved");}}
    for(const auto*id:{"autoMakeup","autoRelease","sidechainHpf","moduleEnabled"})expect(processor.parameters.getParameter(id)!=nullptr,"new automatable parameter is present");
    juce::MidiBuffer midi;auto dry=tone(1000);const auto originalPower=power(dry);set(processor,"moduleEnabled",0);processor.processBlock(dry,midi);expect(std::abs(power(dry)-originalPower)<1e-6f,"bypass passes dry audio exactly");
    auto compressed=tone(1000);set(processor,"moduleEnabled",1);set(processor,"threshold",-30);set(processor,"ratio",10);set(processor,"attack",.1f);processor.processBlock(compressed,midi);expect(power(compressed)<originalPower*.65f,"threshold, ratio, and attack produce compression");const auto meters=processor.meterSnapshot();expect(meters.inputDbfs[0]>meters.outputDbfs[0],"input and output meters reflect gain reduction");expect(meters.gainReductionDb[0]>1&&std::abs(meters.gainReductionDb[0]-meters.gainReductionDb[1])<1e-4f,"linked stereo GR drives both meters");
    GlueCompressorEngine engine;engine.prepare(48000,512,2);GlueCompressorSettings settings;settings.thresholdDbfs=-30;settings.ratio=10;settings.attackMs=.1f;auto bassWithout=tone(40),bassWith=bassWithout;(void)engine.process(bassWithout,settings);engine.reset();settings.sidechainHpf=true;(void)engine.process(bassWith,settings);expect(power(bassWith)>power(bassWithout),"80 Hz detector HPF reduces bass-triggered compression");expect(GlueCompressorEngine::softKneeGainReduction(-11.4f,-11.4f,4)>0,"soft knee acts around threshold");expect(GlueCompressorEngine::automaticMakeupDb(-30,4)>0,"auto makeup computes positive compensation");
    settings={};settings.thresholdDbfs=-30;settings.ratio=8;settings.attackMs=.1f;settings.releaseMs=50;auto reference=tone(1000),fast=reference;engine.reset();(void)engine.process(fast,settings);auto thresholdResult=reference;engine.reset();settings.thresholdDbfs=-3;(void)engine.process(thresholdResult,settings);expect(power(thresholdResult)>power(fast)*1.5f,"live threshold changes compression depth");auto ratioResult=reference;engine.reset();settings.thresholdDbfs=-30;settings.ratio=1;(void)engine.process(ratioResult,settings);expect(difference(ratioResult,reference)<.01f,"live ratio 1:1 removes compression");auto attackResult=reference;engine.reset();settings.ratio=8;settings.attackMs=100;(void)engine.process(attackResult,settings);expect(difference(attackResult,fast)>1,"live attack changes compressor response");auto releaseSource=burst(),fastRelease=releaseSource,slowRelease=releaseSource;engine.reset();settings.attackMs=.1f;settings.releaseMs=50;(void)engine.process(fastRelease,settings);engine.reset();settings.releaseMs=1000;(void)engine.process(slowRelease,settings);expect(difference(slowRelease,fastRelease)>1,"live release changes envelope recovery");auto makeupResult=reference;engine.reset();settings.releaseMs=50;settings.makeupGainDb=6;(void)engine.process(makeupResult,settings);expect(power(makeupResult)>power(fast),"live makeup gain changes output level");settings.moduleEnabled=false;auto bypassed=reference;engine.reset();const auto bypassLevels=engine.process(bypassed,settings);expect(difference(bypassed,reference)<.01f&&std::abs(bypassLevels.gainReductionDb[0])<1.0e-6f,"live bypass passes audio and reports zero gain reduction");
    set(processor,"threshold",-22);juce::MemoryBlock state;processor.getStateInformation(state);DoziGlueCompressorProcessor restored;restored.setStateInformation(state.getData(),static_cast<int>(state.getSize()));expect(std::abs(restored.parameters.getRawParameterValue("threshold")->load()+22)<.01f,"APVTS state restores parameter values");
    if(failures==0)std::cout<<"All DOZI Glue Compressor tests passed\n";return failures==0?0:1;
}
